unsafe fn bffill(ty: &str, base: *mut u8, count: usize, seed: u64) -> bool {
    match ty {
        "CSSData" => { for i in 0..count { let mut st = seed.wrapping_add(i as u64 * 0x1000); bffill_CSSData(base.add(i * 376), &mut st); } true }
        "SSSData" => { for i in 0..count { let mut st = seed.wrapping_add(i as u64 * 0x1000); bffill_SSSData(base.add(i * 368), &mut st); } true }
        "StartMeleeData" => { for i in 0..count { let mut st = seed.wrapping_add(i as u64 * 0x1000); bffill_StartMeleeData(base.add(i * 352), &mut st); } true }
        "VsModeData" => { for i in 0..count { let mut st = seed.wrapping_add(i as u64 * 0x1000); bffill_VsModeData(base.add(i * 360), &mut st); } true }
        _ => true,
    }
}
unsafe fn dump(ty: &str, base: *const u8, count: usize) -> bool {
    match ty {
        "GameModeState" => { for i in 0..count { d_i("#", i as u64); dump_GameModeState(base.add(i * 48)); } true }
        "CSSData" => { for i in 0..count { d_i("#", i as u64); dump_CSSData(base.add(i * 376)); } true }
        "SSSData" => { for i in 0..count { d_i("#", i as u64); dump_SSSData(base.add(i * 368)); } true }
        "StartMeleeData" => { for i in 0..count { d_i("#", i as u64); dump_StartMeleeData(base.add(i * 352)); } true }
        "VsModeData" => { for i in 0..count { d_i("#", i as u64); dump_VsModeData(base.add(i * 360)); } true }
        _ => false,
    }
}

